let LANG = "en";
const _exact = {};
for (const row of T) _exact[row[0].replace(/\s+/g, " ").trim()] = row;

function tr(s) {
  if (LANG === "en" || s == null) return s;
  const i = LANG_INDEX[LANG];
  const lead = s.match(/^\s*/)[0], tail = s.match(/\s*$/)[0];
  const key = s.replace(/\s+/g, " ").trim();
  if (!key) return s;
  const row = _exact[key];
  if (row && row[i]) return lead + row[i] + tail;
  for (const [re, outs] of P) {
    const m = key.match(re);
    if (!m) continue;
    if (!outs) { const inner = tr(m[1]); return lead + key.replace(m[1], inner) + tail; }
    return lead + outs[i - 1].replace(/\$(\d)/g, (_, n) => m[+n]) + tail;
  }
  return s;
}

const SKIP = ".msg.user .body, .msg.assistant .body, .msg.greeting .body, .pre, script, style, td.num, input, textarea";
function translateNode(root) {
  if (LANG === "en" || !root) return;
  if (root.nodeType === 3) {
    const p = root.parentElement;
    if (p && !p.closest(SKIP)) { const t = tr(root.nodeValue); if (t !== root.nodeValue) root.nodeValue = t; }
    return;
  }
  if (root.nodeType !== 1) return;
  if (root.matches && root.matches(".msg.user .body, .msg.assistant .body, .msg.greeting .body, .pre")) return;
  const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const nodes = []; let n;
  while ((n = w.nextNode())) nodes.push(n);
  for (const t of nodes) translateNode(t);
  const els = root.querySelectorAll ? [root, ...root.querySelectorAll("[placeholder],[title],[aria-label]")] : [];
  for (const e of els) for (const a of ["placeholder", "title", "aria-label"]) {
    const v = e.getAttribute && e.getAttribute(a);
    if (v) { const t = tr(v); if (t !== v) e.setAttribute(a, t); }
  }
}

function setLanguage(lang) {
  LANG = LANG_INDEX[lang] !== undefined ? lang : "en";
  document.documentElement.lang = LANG;
  try { localStorage.setItem("nexora_lang", LANG); } catch { /* storage may be blocked */ }
}

(function initI18n() {
  let saved = null;
  try { saved = localStorage.getItem("nexora_lang"); } catch { /* ignore */ }
  setLanguage(saved || "pl");
  const _confirm = window.confirm.bind(window), _prompt = window.prompt.bind(window);
  window.confirm = (m) => _confirm(tr(m));
  window.prompt = (m, d) => _prompt(tr(m), d);
  const obs = new MutationObserver((muts) => {
    if (LANG === "en") return;
    for (const m of muts) {
      if (m.type === "characterData") translateNode(m.target);
      else m.addedNodes.forEach((x) => translateNode(x));
    }
  });
  const start = () => { translateNode(document.body); obs.observe(document.body, { childList: true, subtree: true, characterData: true }); };
  if (document.body) start(); else document.addEventListener("DOMContentLoaded", start);
})();
